// One job per program, so each pc-research run stays under its normal caps (1 fresh program, 1.30 USD stop).
// At most 6 per call: each run can overshoot its 1.30 USD stop (the stop is checked between calls), so one call stays well under 10 USD.
const body = $('Seed-Auftrag').first().json.body ?? {};
const programme = body.programme;
if (!Array.isArray(programme) || !programme.length || programme.length > 6 || !programme.every((p) => typeof p === 'string' && p.trim() && p.length <= 80)) throw new Error('Seed: programme ungültig');
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 3 | 8)).toString(16); });
return programme.map((p) => ({ json: {
  jobId: uuid(), createdAt: new Date().toISOString(), branche: 'seed', team: 'seed', arbeitsort: 'seed', firma: 'Seed',
  programme: [p.trim()], bereiche: ['anfragen'], stunden: { anfragen: 1 }, nervt: 'anfragen', kanaele: [], menge: 'seed', wer: 'seed',
  arbeitstag: '', abende: 'seed', versucht: 'seed', frischeRecherche: true,
} }));
